      'ana.tested': 'Illustrative example. In the code, each strategy is a pure function covered by unit + integration tests.',

      'ia.eyebrow': '<span class="jp">知能</span>AI integration',
      'ia.h2': 'AI that <span class="g">executes</span>, with the right permissions.',
      'ia.p': 'In the corporate portal I develop, the <b>Jarvson</b> agent chats, plans and acts inside the system, with <b>Claude tool use</b>, always within the logged-in user\'s RBAC. Not a decorative chatbot: it does the work.',
      'ia.c1h': 'Tool use with Claude', 'ia.c1p': 'Calls real portal tools via Anthropic\'s <code>input_schema</code> (<code>AsyncAnthropic</code>), in a multi-step planning loop.',
      'ia.c2h': 'Plans before acting', 'ia.c2p': 'Reads run instantly; every <b>write</b> action becomes a plan you confirm, steps linked by <code>$0</code>, <code>$1</code>.',
      'ia.c3h': 'Permission-scoped', 'ia.c3p': 'The agent acts <b>as the logged-in user</b>. No tool bypasses RBAC, it is not a shortcut around access control.',
      'ia.c4h': 'Memory &amp; contexts', 'ia.c4p': 'Keeps facts across conversations and works in "spaces" with standing instructions and reference files.',
      'ia.c5h': 'Neural voice', 'ia.c5p': 'Spoken replies in queued chunks (edge-tts, no quota) with browser Web Speech fallback.',
      'ia.c6h': 'Multi-model', 'ia.c6p': 'Claude Sonnet 5 by default; switch to Haiku (budget) or Opus (top tier) via configuration.',
      'ia.b1': 'Create a Design board and make Ana the lead.',
      'ia.b2': 'That is 2 write actions. I drafted a plan for you to confirm:',
      'ia.planh': '◢ Plan, confirm execution',
      'ia.step1': 'create board "Design"',
      'ia.step2': 'add Ana → lead of <span class="ref">$0</span>',
      'ia.ok': 'Confirm', 'ia.cancel': 'Cancel',
      'ia.foot': 'Reads run instantly · writes only with your confirmation · all inside your RBAC.',

      'sec.eyebrow': '<span class="jp">防御</span>Security',
      'sec.h2': 'Secure by default, across the <span class="g">whole fleet.</span>',
      'sec.p': 'Security is not a single project\'s ornament: it is a baseline repeated across <b>30+ apps</b> in production. Explore the three defense rings.',
      'sec.tab1': '◢ Authentication', 'sec.tab2': '◢ Session &amp; access', 'sec.tab3': '◢ Surface &amp; data',
      'sec.r1h': 'Passwords with bcrypt', 'sec.r1p': 'Hashing via passlib/bcrypt with tunable cost, never plain text, never reversible.',
      'sec.r2h': 'Code-based 2FA', 'sec.r2p': 'Second factor compared with <code>hmac.compare_digest</code>, no timing gap.',
      'sec.r3h': 'JWT access + refresh', 'sec.r3p': 'Short-lived token + refresh, <b>revocable</b>: Redis blacklist with TTL truly invalidates on logout.',
      'sec.r4h': 'httpOnly cookies', 'sec.r4p': 'Token out of JS reach (<code>Secure</code> + <code>SameSite</code>), mitigates XSS and CSRF at once.',
      'sec.r5h': 'Rate limit &amp; login guard', 'sec.r5p': 'slowapi / express-rate-limit + attempt lockout against brute-force and account enumeration.',
      'sec.r6h': 'RBAC as single source', 'sec.r6p': 'Roles in a central catalog; permission checked on every route, even the AI agent acts inside it.',
      'sec.r7h': 'Hardened headers', 'sec.r7p': 'helmet across the fleet: <code>CSP</code>, <code>HSTS</code>, <code>X-Frame-Options: DENY</code>, <code>nosniff</code>.',
      'sec.r8h': 'Timing-safe &amp; HMAC webhooks', 'sec.r8p': 'Constant-time comparisons and signature-verified webhooks before any side effect.',
      'sec.r9h': 'No open ports', 'sec.r9p': 'Exposure only via Cloudflare Tunnel with managed TLS; VPS access by SSH key only.',

      'data.eyebrow': '<span class="jp">データ</span>Data modeling',
      'data.h2': 'The database <span class="g">enforces the rule</span>, not just the code.',
      'data.p': 'PostgreSQL modeled seriously: normalized RBAC, referential integrity with deliberate deletion semantics and versioned migrations, with denormalized event tables where volume demands.',
      'data.l1t': 'Normalized RBAC', 'data.l1d': 'users ⇄ roles ⇄ permissions via association tables with composite PK.',
      'data.l2t': 'Semantic integrity', 'data.l2d': 'CASCADE on children; SET NULL to preserve audit and authorship.',
      'data.l3t': 'Invariants in the schema', 'data.l3d': 'Simple and composite UNIQUE, the database enforces the business rule.',
      'data.l4t': 'Versioned migrations', 'data.l4d': 'Alembic and idempotent incremental SQL (<code>IF NOT EXISTS</code>).',
      'data.l5t': 'Right types &amp; indexes', 'data.l5d': 'Sized SMALLINT/INT, JSONB, arrays and an index on every queried FK.',
      'data.l6t': 'Event tables for volume', 'data.l6d': 'Denormalized time series, optimized for continuous write and read.',
      'data.lbl': 'schema · RBAC + integrity',
      'data.note': '# audit and authorship survive user deletion, a retention decision, not an ORM default.',

      'front.eyebrow': '<span class="jp">画面</span>Frontend',
      'front.h2': 'Interfaces that <span class="g">survive production.</span>',
      'front.p': 'Not backend-only: the same rigor applies on screen. A skill tree built from real evidence in the projects, hover and watch each skill <b>light up in the tree</b> beside it.',
      'front.s1t': 'Production React', 'front.s1d': 'Intentional memoization, 8 routes in <code>lazy</code>+Suspense and post-deploy chunk retry (<code>lazyWithRetry</code> + ErrorBoundary).',
      'front.s2t': 'Custom hooks', 'front.s2d': '<code>useSpinHistory</code> (adaptive delta-poll), <code>useAnalysisSocket</code> (socket + backup poll), <code>useGameLauncher</code> (tested state machine).',
      'front.s3t': 'Client-side real time', 'front.s3d': 'WebSocket with exponential reconnect, dedupe by id, hidden-tab pause and monotonicity guard.',
      'front.s4t': 'Tailor-made dataviz', 'front.s4d': 'Custom gauges with Recharts and hand-written SVG: trigonometric radar and a parametric track that reflows on mobile.',
      'front.s5t': 'Systematic CSS', 'front.s5d': '117 CSS Modules, design tokens, full light/dark themes and grids with up to 7 breakpoints.',
      'front.s6t': 'Microinteractions', 'front.s6d': '3D tilt, lerped cursor, skeletons, native drag-and-drop, toasts with sound, and <code>prefers-reduced-motion</code> respected.',
      'front.s7t': '3D in the browser', 'front.s7d': 'Three.js with dynamic connection graphs and scroll-driven scenes, this site is living proof.',
      'front.s8t': 'Frontend quality', 'front.s8d': 'Vitest + Testing Library on components, E2E with Playwright, list virtualization (homemade and with libs).',
      'front.lbl': 'skill tree · equipped loadout',
      'front.k1': 'CSS Modules in the fleet', 'front.k2': 'Projects on Vite', 'front.k3': 'Custom hooks', 'front.k4': 'Component tests',
      'front.tests': '36+ test files across the fleet · unit + integration · components with Testing Library · E2E with Playwright · coverage v8',

      'pipe.eyebrow': '<span class="jp">能力</span>How I work',
      'pipe.h2': 'From raw data to decision.',
